const input = $input.first().json;
const component = /^[A-Za-z0-9._-]+$/;
const safeComponent = (value, name) => {
  if (typeof value !== 'string' || !component.test(value)) throw new Error(`${name} must be one safe path component`);
  return value;
};
if (input.outcome_code !== 'SEMANTIC_EXECUTION_FAILED') throw new Error('Diagnosis requires SEMANTIC_EXECUTION_FAILED');
const runId = safeComponent(input.run_id, 'run_id');
const executionAttempt = Number(input.execution_attempt);
if (!Number.isInteger(executionAttempt) || executionAttempt < 1) throw new Error('execution_attempt must be a positive integer');
const alias = safeComponent(input.diagnosis_provider ?? input.provider, 'diagnosis_provider').toLowerCase();
const provider = alias === 'gemini' ? 'google' : alias;
if (!['openai', 'anthropic', 'google'].includes(provider)) throw new Error(`Unsupported diagnosis provider: ${provider}`);
const suiteId = input.suite_id == null ? null : safeComponent(input.suite_id, 'suite_id');
const caseId = input.case_id == null ? null : safeComponent(input.case_id, 'case_id');
const runtimeContext = input.runtime_context;
if (!runtimeContext || Array.isArray(runtimeContext) || typeof runtimeContext !== 'object') throw new Error('runtime_context is required');
const runtimeKeys = Object.keys(runtimeContext);
if (runtimeKeys.some((key) => !['transformation_kind', 'source_model', 'target_model'].includes(key))) throw new Error('runtime_context contains an unsupported field');
for (const key of ['transformation_kind', 'source_model', 'target_model']) {
  if (typeof runtimeContext[key] !== 'string' || !runtimeContext[key].trim() || runtimeContext[key].length > 200) throw new Error(`runtime_context.${key} must be a concise string`);
}
return [{ json: {
  run_id: runId, execution_attempt: executionAttempt, provider, suite_id: suiteId, case_id: caseId,
  runtime_context: runtimeContext,
  execution_evidence_path: `/data/artifacts/runs/${runId}/stages/execution/attempts/attempt-${String(executionAttempt).padStart(3, '0')}/evidence.json`,
  evidence_ref: `stages/execution/attempts/attempt-${String(executionAttempt).padStart(3, '0')}/result.json`
} }];

const input = $('Validate Input').first().json;
let executionEvidence;
try { executionEvidence = JSON.parse($input.first().json.execution_evidence_text); } catch (error) { throw new Error(`Invalid execution evidence JSON: ${error.message}`); }
const pairs = executionEvidence.details?.pairs;
if (!Array.isArray(pairs)) throw new Error('Execution evidence has no pairs');
const normalizeRepositoryPath = (raw, name) => {
  const path = String(raw ?? '').replace(/\\/g, '/');
  const marker = 'artifacts/work/';
  const index = path.indexOf(marker);
  if (index < 0) throw new Error(`${name} is not under artifacts/work`);
  const relative = path.slice(index);
  if (relative.includes('..') || relative.includes(',')) throw new Error(`${name} is unsafe`);
  return relative;
};
const failed = pairs.filter((pair) => pair && pair.assertions_passed === false);
const matching = failed.filter((pair) => {
  if (!input.suite_id) return true;
  const suite = String(pair.suite ?? '').replace(/\\/g, '/');
  return suite.endsWith(`/${input.suite_id}`);
});
if (matching.length !== 1) throw new Error(`Expected exactly one failed pair, found ${matching.length}; pass suite_id when needed`);
const pair = matching[0];
const suitePath = normalizeRepositoryPath(pair.suite, 'pair.suite');
const transformationPath = normalizeRepositoryPath(pair.transformation, 'pair.transformation');
const generatedExecutionPath = normalizeRepositoryPath(pair.evidence, 'pair.evidence');
const parts = suitePath.split('/');
const generatedTestsIndex = parts.indexOf('generated_tests');
if (generatedTestsIndex < 0 || parts[generatedTestsIndex + 3] !== 'candidates') throw new Error('Failed pair has an unexpected suite path');
const language = parts[generatedTestsIndex + 1];
const task = parts[generatedTestsIndex + 2];
const testModel = parts[generatedTestsIndex + 4];
const testStrategy = parts[generatedTestsIndex + 5];
const suiteId = parts[generatedTestsIndex + 6];
const component = /^[A-Za-z0-9._-]+$/;
for (const [name, value] of Object.entries({ language, task, testModel, testStrategy, suiteId })) {
  if (typeof value !== 'string' || !component.test(value)) throw new Error(`Unsafe ${name} in failed pair`);
}
if (!['etl', 'atl', 'qvto', 'reactions'].includes(language)) throw new Error(`Unsupported language: ${language}`);
const extension = { etl: 'etl', atl: 'atl', qvto: 'qvto', reactions: 'reactions' }[language];
if (!transformationPath.endsWith(`/${task}.${extension}`)) throw new Error('Failed pair transformation does not match its task');
const dataPath = (repositoryPath) => `/data/artifacts/${repositoryPath.slice('artifacts/work/'.length)}`;
const suiteDataPath = dataPath(suitePath);
const referenceExecutionPath = `/data/artifacts/runs/${input.run_id}/observations/${task}/${testModel}/${testStrategy}/${suiteId}/suite_execution.json`;
const corePaths = [
  '/data/diagnosis_prompts/semantic_failure_diagnosis.md',
  `/data/task_prompts/${language}/${task}.txt`,
  dataPath(transformationPath),
  `${suiteDataPath}/semantic_cases.json`,
  referenceExecutionPath,
  dataPath(generatedExecutionPath),
  `/data/artifacts/runs/${input.run_id}/workspaces/${language}/**/surefire-reports/TEST-*.xml`
];
return [{ json: {
  ...input, language, task, suite_id: suiteId, suite_data_path: suiteDataPath,
  generated_execution_repository_path: generatedExecutionPath,
  core_file_selector: `{${corePaths.join(',')}}`
} }];

const pair = $('Select Failed Pair').first().json;
const files = $input.all().map((item) => ({ name: item.json.evidence_file_name, content: item.json.evidence_file_content }));
const requireFile = (name) => {
  const found = files.filter((file) => file.name === name);
  if (found.length !== 1 || typeof found[0].content !== 'string') throw new Error(`Expected exactly one ${name}`);
  return found[0].content;
};
const parseJson = (text, name) => { try { return JSON.parse(text); } catch (error) { throw new Error(`Invalid ${name}: ${error.message}`); } };
const prompt = requireFile('semantic_failure_diagnosis.md').trim();
const taskDescription = requireFile(`${pair.task}.txt`).trim();
const extension = { etl: 'etl', atl: 'atl', qvto: 'qvto', reactions: 'reactions' }[pair.language];
const generatedTransformation = requireFile(`${pair.task}.${extension}`);
const semanticCases = parseJson(requireFile('semantic_cases.json'), 'semantic_cases.json');
const suiteExecutions = files.filter((file) => file.name === 'suite_execution.json').map((file) => parseJson(file.content, 'suite_execution.json'));
const referenceExecution = suiteExecutions.find((value) => value.inputs?.transformation?.role === 'reference_transformation');
const generatedExecution = suiteExecutions.find((value) => value.inputs?.transformation?.role === 'generated_transformation');
if (!referenceExecution || !generatedExecution) throw new Error('Reference or generated suite_execution.json is missing');
if (referenceExecution.suite_id !== pair.suite_id || generatedExecution.suite_id !== pair.suite_id) throw new Error('Execution evidence identifies another suite');
if (referenceExecution.observation?.reference_valid !== true || referenceExecution.observation?.assertions_passed !== true) throw new Error('Suite did not pass on the reference transformation');
if (generatedExecution.observation?.assertions_passed !== false) throw new Error('Generated transformation execution did not fail');
const decode = (value) => String(value ?? '').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const attribute = (text, name) => decode(text.match(new RegExp(`${name}=\"([^\"]*)\"`, 'i'))?.[1] ?? '');
const failures = [];
for (const report of files.filter((file) => file.name.startsWith('TEST-') && file.name.endsWith('.xml'))) {
  for (const testcase of report.content.matchAll(/<testcase\b([^>]*)>([\s\S]*?)<\/testcase>/gi)) {
    const failure = testcase[2].match(/<(failure|error)\b([^>]*)>([\s\S]*?)<\/\1>/i) ?? testcase[2].match(/<(failure|error)\b([^>]*)\/>/i);
    if (!failure) continue;
    const message = attribute(failure[2], 'message');
    const stackTrace = decode(String(failure[3] ?? '').replace(/^<!\[CDATA\[/, '').replace(/\]\]>$/, '').trim());
    const expectedActual = `${message}\n${stackTrace}`.match(/expected(?:\s*:)?\s*<([^>]*)>\s*(?:but was|actual(?:\s*:)?)(?:\s*:)?\s*<([^>]*)>/i);
    failures.push({
      test_method: attribute(testcase[1], 'name'), test_class: attribute(testcase[1], 'classname'),
      type: attribute(failure[2], 'type') || failure[1].toLowerCase(), message,
      expected: expectedActual?.[1] ?? null, actual: expectedActual?.[2] ?? null, stack_trace: stackTrace
    });
  }
}
if (!failures.length) throw new Error('No Surefire failure/error found');
const sanitize = (value) => {
  const words = String(value).split(/[^A-Za-z0-9]+/).filter(Boolean);
  if (!words.length) return 'generatedSemanticCase';
  const [first, ...rest] = words;
  let method = first.slice(0, 1).toLowerCase() + first.slice(1) + rest.map((word) => word.slice(0, 1).toUpperCase() + word.slice(1)).join('');
  if (!/^[A-Za-z_]/.test(method)) method = `case${method}`;
  return method;
};
const testClass = String(semanticCases.testClass ?? '');
const tests = Array.isArray(semanticCases.tests) ? semanticCases.tests : [];
const matching = tests.flatMap((semanticCase) => {
  const method = sanitize(semanticCase.name);
  return failures.filter((failure) => failure.test_method === method && (!testClass || failure.test_class === testClass || failure.test_class.endsWith(`.${testClass}`))).map((failure) => ({ semanticCase, failure }));
}).filter((entry) => !pair.case_id || entry.semanticCase.name === pair.case_id);
if (matching.length !== 1) throw new Error(`Expected exactly one failing case, found ${matching.length}; pass case_id when needed`);
const { semanticCase, failure } = matching[0];
const modelSlots = Array.isArray(semanticCase.models) ? semanticCase.models : (Array.isArray(semanticCases.models) ? semanticCases.models : []);
const fixturePaths = [...new Set(modelSlots.map((model) => model.path).filter(Boolean).map(String))].sort();
if (!fixturePaths.length) throw new Error('Failing case has no fixture files');
if (fixturePaths.some((path) => !/^models\/[A-Za-z0-9._-]+\.(?:xmi|xml|model)$/.test(path))) throw new Error('Failing case contains an unsupported fixture path');
const fixtureDataPaths = fixturePaths.map((path) => `${pair.suite_data_path}/${path}`);
const referenceResult = {
  reference_valid: true, assertions_passed: true, technically_executable: referenceExecution.observation.technically_executable
};
const generatedObservation = generatedExecution.observation;
const generatedResult = {
  technically_executable: generatedObservation.technically_executable, assertions_evaluated: generatedObservation.assertions_evaluated,
  assertions_passed: generatedObservation.assertions_passed, failure_stage: generatedObservation.failure_stage,
  error_summary: generatedObservation.error_summary, timed_out: generatedObservation.timed_out, maven_exit_code: generatedObservation.maven_exit_code
};
return [{ json: {
  run_id: pair.run_id, provider: pair.provider, evidence_ref: pair.evidence_ref, runtime_context: pair.runtime_context,
  case_id: semanticCase.name, system_prompt: prompt, task_description: taskDescription,
  generated_transformation: generatedTransformation, failing_case: semanticCase, reference_result: referenceResult,
  generated_result: generatedResult, failure, fixture_names: fixturePaths.map((path) => path.slice('models/'.length)),
  fixture_file_selector: fixtureDataPaths.length === 1 ? fixtureDataPaths[0] : `{${fixtureDataPaths.join(',')}}`
} }];

const selected = $('Select Failing Case').first().json;
const fixtureItems = $input.all();
if (fixtureItems.length !== selected.fixture_names.length) throw new Error('Not every required fixture was loaded');
const fixtures = fixtureItems.map((item, index) => {
  const fileName = item.binary?.data?.fileName ?? selected.fixture_names[index];
  const content = item.json.fixture_content;
  if (!selected.fixture_names.includes(fileName) || typeof content !== 'string') throw new Error('Unexpected fixture file');
  return { path: `models/${fileName}`, content };
}).sort((left, right) => left.path.localeCompare(right.path));
const resolved = $('Resolve Exact Metamodels').first().json;
const metamodels = Array.isArray(resolved.metamodels) ? resolved.metamodels.map((model) => ({ path: model.path, content: model.content })) : [];
const bundle = {
  task_description: selected.task_description,
  runtime_context: selected.runtime_context,
  metamodels,
  generated_transformation: selected.generated_transformation,
  failing_case: selected.failing_case,
  fixtures,
  reference_result: selected.reference_result,
  generated_result: selected.generated_result,
  failure: selected.failure
};
return [{ json: {
  run_id: selected.run_id, provider: selected.provider, evidence_ref: selected.evidence_ref, case_id: selected.case_id,
  system_prompt: selected.system_prompt, user_prompt: JSON.stringify(bundle, null, 2)
} }];

const source = $input.first().json;
const context = $('Assemble Diagnosis Bundle').first().json;
const raw = [source.text, source.content, source.output, source.response, source.message?.content, source.choices?.[0]?.message?.content].find((value) => typeof value === 'string' && value.trim());
if (!raw) throw new Error('Diagnosis LLM returned no text');
let parsed;
try { parsed = JSON.parse(raw.trim()); } catch (error) { throw new Error(`Diagnosis LLM returned invalid JSON: ${error.message}`); }
if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error('Diagnosis response must be one JSON object');
const requiredKeys = ['case_id', 'source_classification', 'failure_category', 'confidence', 'feedback_summary', 'evidence'];
if (JSON.stringify(Object.keys(parsed).sort()) !== JSON.stringify([...requiredKeys].sort())) throw new Error(`Diagnosis response must contain exactly: ${requiredKeys.join(', ')}`);
if (parsed.case_id !== context.case_id) throw new Error('Diagnosis case_id does not match the failing case');
const sourceClassification = String(parsed.source_classification ?? '').trim().toUpperCase();
const classificationMap = { LIKELY_TRANSFORMATION_DEFECT: 'TRANSFORMATION_DEFECT', LIKELY_TEST_DEFECT: 'TEST_DEFECT', AMBIGUOUS: 'AMBIGUOUS' };
const classification = classificationMap[sourceClassification];
if (!classification) throw new Error(`Invalid source_classification: ${sourceClassification}`);
const failureCategory = String(parsed.failure_category ?? '').trim().toUpperCase();
if (!/^[A-Z][A-Z0-9_]{1,63}$/.test(failureCategory)) throw new Error('failure_category must be concise UPPER_SNAKE_CASE');
const confidence = String(parsed.confidence ?? '').trim().toLowerCase();
if (!['low', 'medium', 'high'].includes(confidence)) throw new Error(`Invalid confidence: ${confidence}`);
const feedbackSummary = String(parsed.feedback_summary ?? '').trim();
if (!feedbackSummary || feedbackSummary.length > 1000) throw new Error('feedback_summary must be 1-1000 characters');
if (!Array.isArray(parsed.evidence) || parsed.evidence.length < 1 || parsed.evidence.length > 8 || parsed.evidence.some((entry) => typeof entry !== 'string' || !entry.trim() || entry.length > 1000)) throw new Error('evidence must contain 1-8 concise strings');
const modelByProvider = { openai: 'gpt-5', anthropic: 'claude-sonnet-4-20250514', google: 'models/gemini-2.5-pro' };
const model = modelByProvider[context.provider];
if (!model) throw new Error(`No diagnosis model configured for provider: ${context.provider}`);
return [{ json: {
  schema_version: '1.0', classification, evidence_ref: context.evidence_ref,
  rationale: `${feedbackSummary} Evidence: ${parsed.evidence.map((entry) => entry.trim()).join(' | ')}`,
  provider: context.provider, model, created_at: new Date().toISOString(), run_id: context.run_id,
  case_id: context.case_id, source_classification: sourceClassification, failure_category: failureCategory,
  confidence, feedback_summary: feedbackSummary, evidence: parsed.evidence.map((entry) => entry.trim())
} }];

const persisted = $input.first().json;
const verdict = $('Attach Diagnosis Provenance').first().json;
return [{ json: {
  case_id: verdict.case_id, classification: verdict.classification, source_classification: verdict.source_classification,
  failure_category: verdict.failure_category, confidence: verdict.confidence, feedback_summary: verdict.feedback_summary,
  evidence: verdict.evidence, provider: persisted.provider, model: persisted.model, created_at: persisted.created_at,
  attempt: persisted.attempt, artifact: persisted.artifact
} }];
